<?php
declare(strict_types=1);
namespace App\Interfaces\Http\Controller\Quiz;
use App\Application\Quiz\SubmitQuiz\SubmitQuizCommand;use App\Application\Quiz\SubmitQuiz\SubmitQuizHandler;use App\Interfaces\Http\Controller\JsonController;use App\Interfaces\Http\Support\ErrorMapper;
final class SubmitQuizController extends JsonController { public function __construct(private SubmitQuizHandler $handler) {} public function __invoke(): void { try{$b=$this->requestJson(); $quizId=(string)($b['quizId'] ?? $b['quiz_id'] ?? ''); $studentName=(string)($b['studentName'] ?? $b['student_name'] ?? ''); $score=(int)($b['score'] ?? 0); $total=(int)($b['total'] ?? $b['total_questions'] ?? 0); $duration=(int)($b['duration'] ?? $b['duration_seconds'] ?? 0); $answersRaw=$b['answersJson'] ?? $b['answers_json'] ?? $b['answers'] ?? null; $answersJson=is_string($answersRaw)?$answersRaw:json_encode($answersRaw ?? [], JSON_THROW_ON_ERROR); foreach(['quizId'=>$quizId,'studentName'=>$studentName,'answersJson'=>$answersJson] as $k=>$v){ if($v===''){ $this->json(400,['error'=>$k.' is required']); return; }} $this->handler->handle(new SubmitQuizCommand($quizId,$studentName,$score,$total,$duration,$answersJson)); $this->json(200,['ok'=>true]); }catch(\Throwable $e){[$s,$m]=ErrorMapper::map($e);$this->json($s,['error'=>$m]);} }}
